rows.declaration:
pub struct Row {
    pub key: String,
    pub expected: String,
    pub class: String,
    /// RF-CANCEL's recommended (binding, net-governed) scale; None elsewhere.
    pub scale: Option<String>,
}

pub struct Control {
    pub id: String,
    pub discriminates: bool,
    pub kind: ControlKind,
}

pub enum ControlKind {
    /// R1's violating values of a value control, by key.
    Value(Vec<(String, String)>),
    /// An outcome control: the defect it describes.
    Outcome(String),
}

pub struct SpringSpec {
    /// R1's `S.<node>.<index>`.
    pub key: String,
    pub id: u32,
    pub node: u32,
    pub translation: bool,
    /// The global component (0–5) of a global-axis spring; None for a
    /// directional one.
    pub axis: Option<usize>,
    pub direction: [f64; 3],
    pub stiffness: f64,
}

pub struct K6Model {
    pub id: String,
    pub source: String,
    pub family: Family,
    pub section: FrameSection,
    /// (label, coordinates), in the model's node order (node index = position).
    pub nodes: Vec<(String, [f64; 3])>,
    /// (label, node i, node j, y_reference), in the model's member order.
    pub members: Vec<(String, usize, usize, [f64; 3])>,
    /// (node, restrained UX UY UZ RX RY RZ), ascending node.
    pub restraints: Vec<(usize, [bool; 6])>,
    /// (global DOF, value), ascending DOF, nonzero only.
    pub loads: Vec<(usize, f64)>,
}
